using System;
using UnityEngine;

namespace SignalLost.Inventory
{
    /// <summary>
    /// The model and icon for each scrap type (meeting notes 10-23), so floor drops, the HUD, the pockets menu and the
    /// shop all show the same thing. Generated by ScrapAssetBuilder into Resources, so runtime code finds it without
    /// scene references: <see cref="Model"/> and <see cref="Icon"/>. Missing entries fall back to plain shapes.
    /// </summary>
    [CreateAssetMenu(menuName = "Signal Lost/Scrap Catalog")]
    public sealed class ScrapCatalog : ScriptableObject
    {
        public const string ResourcePath = "SignalLost/ScrapCatalog";

        [Serializable]
        public struct Entry
        {
            public ScrapType type;
            [Tooltip("The pickup model: about 0.4 m across, resting upright on y = 0.")]
            public GameObject model;
            public Sprite icon;
        }

        [SerializeField] private Entry[] entries = Array.Empty<Entry>();

        private static ScrapCatalog loaded;
        private static bool searched;

        private static ScrapCatalog Instance
        {
            get
            {
                if (!searched) { loaded = Resources.Load<ScrapCatalog>(ResourcePath); searched = true; }
                return loaded;
            }
        }

        public static GameObject Model(ScrapType type) => Find(type).model;
        public static Sprite Icon(ScrapType type) => Find(type).icon;

        private static Entry Find(ScrapType type)
        {
            ScrapCatalog catalog = Instance;
            if (catalog != null)
                foreach (Entry entry in catalog.entries)
                    if (entry.type == type) return entry;
            return default;
        }

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetStatics()
        {
            loaded = null;
            searched = false;
        }
    }
}
